1	/**
2	 * A member a library renamed on a type it publishes, applied where the compiler
3	 * itself resolved the receiver.
4	 *
5	 * `TS2339: Property 'addAll' does not exist on type 'EntityAdapter<…>'` is the
6	 * shape a renamed method leaves behind, and it is a harder shape to answer than
7	 * a renamed export. TypeScript offers no successor for it — there is no "did you
8	 * mean", because the checker's own spelling heuristic does not connect `addAll`
9	 * to `setAll` — so the successor cannot come from the diagnostic the way
10	 * {@link applySuggestedExportRenames} takes it. It has to come from somewhere,
11	 * and the only honest options are a name a person wrote down or a name invented
12	 * at rewrite time. This capability takes the first and refuses to take the
13	 * second.
14	 *
15	 * What the diagnostic does supply is the part a table cannot: the receiver. The
16	 * message names the *declared type* of the expression the member was reached
17	 * through, which is the compiler's own binding resolution against the installed
18	 * closure — not a guess about which `adapter` in the module is an entity
19	 * adapter, and not a textual match on a method name that any object might carry.
20	 * A rename is written only at a position where the compiler has already said
21	 * "the thing on the left of this dot is that type".
22	 *
23	 * The written-down half is then checked against the installed tree before
24	 * anything is written, and the check is two-sided: the type has to publish the
25	 * successor and it has to not publish the name being replaced. A tree that still
26	 * has `addAll` is a tree where this diagnostic means something else, and a tree
27	 * without `setAll` is one where the rename would move the failure rather than
28	 * answer it. Either way the rename is refused by name and the site is left for a
29	 * reading nobody has taken yet.
30	 */
31	
32	import { charNotIn, createRegExp, digit, exactly, oneOrMore } from 'magic-regexp';
33	import { compareStrings } from './angular-target-cell.ts';
34	import {
35		applySourceEdits,
36		forEachNode,
37		lineOf,
38		offsetOfPosition,
39		parseModule,
40		type AstNode,
41		type SemanticModule,
42		type SourceEdit,
43	} from './semantic-module.ts';
44	
45	const CAPABILITY = 'Declared type member rename';
46	
47	/**
48	 * One `TS2339`, decomposed: the member the expression reached for, and the head
49	 * of the declared type the compiler resolved its receiver to. `line` and
50	 * `column` are the compiler's own 1-based pair, pointing at the member name.
51	 */
52	export type MissingMemberDiagnostic = Readonly<{
53		line: number;
54		column: number;
55		member: string;
56		/** `EntityAdapter` of `EntityAdapter<Readonly<ProjectCopy>>`. */
57		declaredType: string;
58	}>;
59	
60	/**
61	 * One member rename a library documented, as a claim to be checked. `package`
62	 * and `type` say which declaration the claim is about; nothing is written on the
63	 * strength of this record alone.
64	 */
65	export type DocumentedMemberRename = Readonly<{
66		package: string;
67		type: string;
68		from: string;
69		to: string;
70		/** The release that made the rename, for the record and the refusal messages. */
71		since: string;
72	}>;
73	
74	/**
75	 * Every member one installed type declares, following the interfaces it extends.
76	 * `complete` is the reading's own statement about itself: a member list that
77	 * could not follow an extends clause proves no name absent, and a rename that
78	 * turned on such a list would be turning on ignorance.
79	 */
80	export type TypeMemberSurfaceReading = Readonly<{
81		package: string;
82		version: string;
83		type: string;
84		members: readonly string[];
85		complete: boolean;
86	}>;
87	
88	export type MemberRenameChange = Readonly<{
89		kind: 'declared-type-member-rename';
90		line: number;
91		declaredType: string;
92		from: string;
93		to: string;
94	}>;
95	
96	export type MemberRenameMigration = Readonly<{
97		path: string;
98		source: string;
99		changed: boolean;
100		changes: readonly MemberRenameChange[];
101		unhandled: readonly string[];
102	}>;
103	
104	/**
105	 * The renames this adapter has been told about.
106	 *
107	 * Every entry is inert until a surface reading proves it describes the installed
108	 * tree. The list is short on purpose: it holds renames of members on types an
109	 * application reaches through a library's own factory, where the receiver is
110	 * resolvable by the compiler and the successor is not.
111	 */
112	export const DOCUMENTED_MEMBER_RENAMES: readonly DocumentedMemberRename[] = Object.freeze([
113		Object.freeze({
114			package: '@ngrx/entity',
115			type: 'EntityAdapter',
116			from: 'addAll',
117			to: 'setAll',
118			since: '@ngrx/entity 10',
119		}),
120	]);
121	
122	/** The head of a printed type: `EntityAdapter` of `EntityAdapter<Readonly<X>>`. */
123	export function typeHead(printed: string): string {
124		const open = printed.indexOf('<');
125		return open === -1 ? printed : printed.slice(0, open);
126	}
127	
128	/** The property identifier of a member expression that starts exactly at `offset`. */
129	function propertyAt(module: SemanticModule, offset: number): AstNode | null {
130		let found: AstNode | null = null;
131		forEachNode(module.ast, (node) => {
132			if (found !== null) return;
133			if (node.type !== 'MemberExpression') return;
134			const property = node.property;
135			if (node.computed) return;
136			if (property.type !== 'Identifier') return;
137			if (property.start === offset) found = property;
138		});
139		return found;
140	}
141	
142	/**
143	 * Apply the documented renames to one module, where the compiler resolved the
144	 * receiver and the closure proves the rename.
145	 */
146	export function renameDeclaredTypeMembers(
147		path: string,
148		source: string,
149		diagnostics: readonly MissingMemberDiagnostic[],
150		renames: readonly DocumentedMemberRename[],
151		surfaces: readonly TypeMemberSurfaceReading[],
152	): MemberRenameMigration {
153		const module = parseModule(CAPABILITY, path, source);
154		const edits: SourceEdit[] = [];
155		const changes: MemberRenameChange[] = [];
156		const unhandled: string[] = [];
157		const refuse = (line: number, reason: string): void => {
158			unhandled.push(`${path} line ${String(line)}: ${reason}`);
159		};
160		for (const diagnostic of diagnostics) {
161			const { line, column, member, declaredType } = diagnostic;
162			const candidates = renames.filter(
163				(entry) => entry.type === declaredType && entry.from === member,
164			);
165			if (candidates.length === 0) continue;
166			if (candidates.length > 1) {
167				refuse(
168					line,
169					`${String(candidates.length)} renames claim '${declaredType}.${member}', so which one ` +
170						'describes this tree is not established',
171				);
172				continue;
173			}
174			const rename = candidates[0] as DocumentedMemberRename;
175			const surface = surfaces.find(
176				(entry) => entry.package === rename.package && entry.type === rename.type,
177			);
178			if (surface === undefined) {
179				refuse(line, `no member surface was read for '${rename.package}' ${rename.type}`);
180				continue;
181			}
182			if (!surface.complete) {
183				refuse(
184					line,
185					`the member surface of ${rename.type} in '${rename.package}'@${surface.version} is ` +
186						`incomplete, so it cannot establish that ${rename.to} is declared or that ` +
187						`${rename.from} is not`,
188				);
189				continue;
190			}
191			if (!surface.members.includes(rename.to)) {
192				refuse(
193					line,
194					`${rename.since} is said to have renamed ${rename.from} to ${rename.to}, and ` +
195						`${rename.type} in '${rename.package}'@${surface.version} does not declare ${rename.to}`,
196				);
197				continue;
198			}
199			if (surface.members.includes(rename.from)) {
200				refuse(
201					line,
202					`${rename.type} in '${rename.package}'@${surface.version} still declares ${rename.from}, ` +
203						'so the diagnostic does not describe this closure and the rename would be a rewrite ' +
204						'of working code',
205				);
206				continue;
207			}
208			const offset = offsetOfPosition(source, line, column);
209			if (offset === null) {
210				refuse(line, `column ${String(column)} is not a position in this file`);
211				continue;
212			}
213			if (source.slice(offset, offset + member.length) !== member) {
214				refuse(line, `column ${String(column)} is not where '${member}' is written`);
215				continue;
216			}
217			const property = propertyAt(module, offset);
218			if (property === null) {
219				refuse(
220					line,
221					`column ${String(column)} is not the property of a static member expression, so the ` +
222						`${member} the compiler named cannot be placed`,
223				);
224				continue;
225			}
226			edits.push({ start: property.start, end: property.end, text: rename.to });
227			changes.push({
228				kind: 'declared-type-member-rename',
229				line: lineOf(source, property.start),
230				declaredType,
231				from: rename.from,
232				to: rename.to,
233			});
234		}
235		const migrated = applySourceEdits(source, edits);
236		return Object.freeze({
237			path,
238			source: migrated,
239			changed: migrated !== source,
240			changes: Object.freeze(changes),
241			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
242		});
243	}
244	
245	/**
246	 * The `TS2339` lines of a build log, decomposed into diagnostics by file.
247	 *
248	 * Only the lines whose message carries a declared type are read. A TS2339 that
249	 * names no type — the ones a component's own template raises against the
250	 * component class — resolves no receiver, and a capability that treated the two
251	 * alike would be renaming members on whatever object happened to be there.
252	 */
253	export function readMissingMembers(
254		log: string,
255	): ReadonlyMap<string, readonly MissingMemberDiagnostic[]> {
256		const found = new Map<string, MissingMemberDiagnostic[]>();
257		for (const line of log.split('\n')) {
258			const head = DIAGNOSTIC_HEAD.exec(line.trim())?.groups;
259			const message = MISSING_PROPERTY.exec(line)?.groups;
260			if (head === undefined || message === undefined) continue;
261			const entry: MissingMemberDiagnostic = Object.freeze({
262				line: Number(head['line']),
263				column: Number(head['column']),
264				member: message['member'] as string,
265				declaredType: typeHead(message['type'] as string),
266			});
267			const list = found.get(head['file'] as string);
268			if (list === undefined) found.set(head['file'] as string, [entry]);
269			else list.push(entry);
270		}
271		return new Map([...found].map(([file, list]) => [file, Object.freeze(list)]));
272	}
273	
274	/** The position and code the builder prints in front of a diagnostic's message. */
275	const DIAGNOSTIC_HEAD = createRegExp(
276		oneOrMore(charNotIn(' \t\n:'))
277			.as('file')
278			.and(exactly(':'))
279			.and(oneOrMore(digit).as('line'))
280			.and(exactly(':'))
281			.and(oneOrMore(digit).as('column'))
282			.and(exactly(' - error TS2339: ')),
283	);
284	
285	/** The message body, which names the member and the type its receiver resolved to. */
286	const MISSING_PROPERTY = createRegExp(
287		exactly("Property '")
288			.and(oneOrMore(charNotIn("'")).as('member'))
289			.and(exactly("' does not exist on type '"))
290			.and(oneOrMore(charNotIn("'")).as('type'))
291			.and(exactly("'.")),
292	);
