28	import { readdir, readFile, writeFile } from 'node:fs/promises';
29	import { existsSync } from 'node:fs';
30	import * as path from 'pathe';
31	import {
32		parameteriseBaseClasses,
33		readMissingMembers,
34		readUnparameterisedBaseClasses,
35		renameDeclaredTypeMembers,
36		DOCUMENTED_MEMBER_RENAMES,
37		type GenericBaseClassReading,
38		type BaseTypeParameterReading,
