47	/** Every `.d.ts` beneath a directory, skipping the bundled ESM re-emissions. */
48	async function declarationsBelow(root: string): Promise<readonly string[]> {
49		const found: string[] = [];
50		const walk = async (directory: string): Promise<void> => {
51			for (const entry of await readdir(directory, { withFileTypes: true })) {
52				if (entry.name === 'esm2022' || entry.name === 'fesm2022' || entry.name === 'node_modules')
53					continue;
54				const full = path.join(directory, entry.name);
55				if (entry.isDirectory()) await walk(full);
56				else if (entry.name.endsWith('.d.ts')) found.push(full);
57			}
58		};
59		await walk(root);
60		return Object.freeze(found.sort());
61	}
62	
63	/** The installed version a package declares, or `unknown`. */
64	async function versionOf(tree: string, name: string): Promise<string> {
65		try {
66			const manifest = JSON.parse(
67				await readFile(path.join(tree, 'node_modules', name, 'package.json'), 'utf8'),
68			) as Readonly<{ version?: unknown }>;
69			return typeof manifest.version === 'string' ? manifest.version : 'unknown';
70		} catch {
71			return 'unknown';
72		}
73	}
