75	/**
76	 * The span of a bracketed run starting at `open`, respecting nesting.
77	 * Returns the index just past the closing bracket, or -1 when it is unbalanced.
78	 */
79	function spanOf(text: string, open: number, opener: string, closer: string): number {
80		let depth = 0;
81		for (let index = open; index < text.length; index += 1) {
82			const character = text[index];
83			if (character === opener) depth += 1;
84			else if (character === closer) {
85				depth -= 1;
86				if (depth === 0) return index + 1;
87			}
88		}
89		return -1;
90	}
91	
92	/** Split a bracketed list on its top-level commas. */
93	function splitTopLevel(text: string): readonly string[] {
94		const parts: string[] = [];
95		let depth = 0;
96		let start = 0;
97		for (let index = 0; index < text.length; index += 1) {
98			const character = text[index];
99			if (character === '<' || character === '(' || character === '{' || character === '[') depth += 1;
100			else if (character === '>' || character === ')' || character === '}' || character === ']')
101				depth -= 1;
102			else if (character === ',' && depth === 0) {
103				parts.push(text.slice(start, index));
104				start = index + 1;
105			}
106		}
107		parts.push(text.slice(start));
108		return Object.freeze(parts.map((part) => part.trim()).filter((part) => part !== ''));
109	}
110	
111	/** The head of a printed type reference: `A` of `A<B<C>>`. */
112	function headOf(text: string): string {
113		const open = text.indexOf('<');
114		return (open === -1 ? text : text.slice(0, open)).trim();
115	}
116	
117	/** One declaration's `<…>` parameter list, decomposed as the tree declares it. */
118	function readTypeParameters(declaration: string): readonly BaseTypeParameterReading[] {
119		const open = declaration.indexOf('<');
120		if (open === -1) return Object.freeze([]);
121		const close = spanOf(declaration, open, '<', '>');
122		if (close === -1) return Object.freeze([]);
123		return Object.freeze(
124			splitTopLevel(declaration.slice(open + 1, close - 1)).map((text) => {
125				const equals = text.indexOf('=');
126				const beforeDefault = equals === -1 ? text : text.slice(0, equals);
127				const extendsAt = beforeDefault.indexOf(' extends ');
128				return Object.freeze({
129					name: (extendsAt === -1 ? beforeDefault : beforeDefault.slice(0, extendsAt)).trim(),
130					constraint:
131						extendsAt === -1 ? null : headOf(beforeDefault.slice(extendsAt + ' extends '.length)),
132					hasDefault: equals !== -1,
133				});
134			}),
135		);
136	}
137	
138	/** The specifier a declaration file imports `name` from, when it imports it. */
139	function specifierOfImport(source: string, name: string): string | null {
140		for (const line of source.split('\n')) {
141			if (!line.startsWith('import ')) continue;
142			const open = line.indexOf('{');
143			const close = line.indexOf('}');
144			if (open === -1 || close === -1) continue;
145			const names = splitTopLevel(line.slice(open + 1, close)).map((entry) =>
146				(entry.split(' as ')[0] ?? entry).trim(),
147			);
148			if (!names.includes(name)) continue;
149			const quote = line.indexOf("'", close);
150			if (quote === -1) continue;
151			const end = line.indexOf("'", quote + 1);
152			if (end === -1) continue;
153			return line.slice(quote + 1, end);
154		}
155		return null;
156	}
157	
158	/**
159	 * The member names an interface body declares, at its own brace depth.
160	 *
161	 * Only braces are counted. A declaration's angle brackets and parentheses close
162	 * on the line that opens them, and `=>` in a function-typed property would make
163	 * an angle-bracket counter go negative on a line that nests nothing.
164	 */
165	function readMembers(body: string): readonly string[] {
166		const names: string[] = [];
167		let depth = 0;
168		for (const raw of body.split('\n')) {
169			const line = raw.trim();
170			const before = depth;
171			for (const character of line) {
172				if (character === '{') depth += 1;
173				else if (character === '}') depth -= 1;
174			}
175			if (before !== 0) continue;
176			const member = /^(?:readonly\s+)?(?<name>[A-Za-z_$][\w$]*)\s*[<(?:]/u.exec(line)?.groups?.[
177				'name'
178			];
179			if (member !== undefined) names.push(member);
180		}
181		return Object.freeze([...new Set(names)].sort());
182	}
183	
184	/**
185	 * The declaration of one generic base class an application extends, and the
186	 * companion type the same tree publishes for it.
187	 *
188	 * The companion is looked for by the pairing the declaration itself establishes:
189	 * a class `X` whose parameter is constrained to `C` is paired with the interface
190	 * `XConfig` that extends `C`, in the package `C` comes from. The pairing is a
191	 * shape to look for, not a fact to assume — the interface has to be there, it
192	 * has to extend the constraint, and it has to declare members of its own, or the
193	 * reading returns no companion and the adapter refuses.
194	 */
195	export async function readGenericBaseClass(
196		tree: string,
197		name: string,
198		specifier: string,
199	): Promise<GenericBaseClassReading> {
200		const modules = path.join(tree, 'node_modules');
201		const empty = Object.freeze({
202			name,
203			specifier,
204			declaration: 'not found',
205			parameters: Object.freeze([]),
206			companion: null,
207		});
208		const packageName = specifier.startsWith('@')
209			? specifier.split('/').slice(0, 2).join('/')
210			: (specifier.split('/')[0] as string);
211		const root = path.join(modules, packageName);
212		if (!existsSync(root)) return empty;
213		const pattern = new RegExp(String.raw`declare (?:abstract )?class ${name}\s*<`, 'u');
214		for (const file of await declarationsBelow(root)) {
215			const source = await readFile(file, 'utf8');
216			const match = pattern.exec(source);
217			if (match === null) continue;
218			const open = source.indexOf('<', match.index);
219			const close = spanOf(source, open, '<', '>');
220			if (close === -1) continue;
221			const parameters = readTypeParameters(source.slice(open, close));
222			const constraint = parameters[0]?.constraint ?? null;
223			const companion =
224				constraint === null
225					? null
226					: await readCompanionType(
227							modules,
228							`${name}Config`,
229							specifierOfImport(source, constraint) ?? packageName,
230						);
231			return Object.freeze({
232				name,
233				specifier,
234				declaration: path.relative(modules, file),
235				parameters,
236				companion,
237			});
238		}
239		return empty;
240	}
241	
242	/** The companion interface, if the package that publishes the constraint has one. */
243	async function readCompanionType(
244		modules: string,
245		name: string,
246		specifier: string,
247	): Promise<CompanionTypeReading | null> {
248		const packageName = specifier.startsWith('@')
249			? specifier.split('/').slice(0, 2).join('/')
250			: (specifier.split('/')[0] as string);
251		const root = path.join(modules, packageName);
252		if (!existsSync(root)) return null;
253		const pattern = new RegExp(String.raw`export interface ${name}\s*[<{]`, 'u');
254		for (const file of await declarationsBelow(root)) {
255			const source = await readFile(file, 'utf8');
256			const match = pattern.exec(source);
257			if (match === null) continue;
258			const brace = source.indexOf('{', match.index);
259			const head = source.slice(match.index, brace);
260			const extendsAt = head.indexOf(' extends ');
261			const close = spanOf(source, brace, '{', '}');
262			if (close === -1) continue;
263			return Object.freeze({
264				name,
265				specifier: packageName,
266				extendsConstraint:
267					extendsAt === -1 ? null : headOf(head.slice(extendsAt + ' extends '.length)),
268				members: readMembers(source.slice(brace + 1, close - 1)),
269			});
270		}
271		return null;
272	}
273	
274	/**
275	 * Every member one installed type declares, following the interfaces it extends
276	 * within the same package. An extends clause that could not be followed makes
277	 * the reading incomplete, and an incomplete reading proves no name absent.
278	 */
279	export async function readTypeMemberSurface(
280		tree: string,
281		packageName: string,
282		type: string,
283	): Promise<TypeMemberSurfaceReading> {
284		const root = path.join(tree, 'node_modules', packageName);
285		const version = await versionOf(tree, packageName);
286		const absent = Object.freeze({
287			package: packageName,
288			version,
289			type,
290			members: Object.freeze([]),
291			complete: false,
292		});
293		if (!existsSync(root)) return absent;
294		const files = await declarationsBelow(root);
295		const sources = new Map<string, string>();
296		for (const file of files) sources.set(file, await readFile(file, 'utf8'));
297		const members = new Set<string>();
298		const seen = new Set<string>();
299		let complete = true;
300		const visit = (interfaceName: string): void => {
301			if (seen.has(interfaceName)) return;
302			seen.add(interfaceName);
303			const pattern = new RegExp(String.raw`(?:export )?interface ${interfaceName}\s*[<{]`, 'u');
304			let matched = false;
305			for (const [, source] of sources) {
306				const match = pattern.exec(source);
307				if (match === null) continue;
308				matched = true;
309				const brace = source.indexOf('{', match.index);
310				const head = source.slice(match.index, brace);
311				const close = spanOf(source, brace, '{', '}');
312				if (close === -1) {
313					complete = false;
314					break;
315				}
316				for (const member of readMembers(source.slice(brace + 1, close - 1))) members.add(member);
317				const extendsAt = head.indexOf(' extends ');
318				if (extendsAt !== -1)
319					for (const parent of splitTopLevel(head.slice(extendsAt + ' extends '.length)))
320						visit(headOf(parent));
321				break;
322			}
323			if (!matched) complete = false;
324		};
325		visit(type);
326		return Object.freeze({
327			package: packageName,
328			version,
329			type,
330			members: Object.freeze([...members].sort()),
331			complete,
332		});
333	}
334	
335	/** The base-class round, driven by the compiler's own TS2314 lines. */
336	async function baseClassRound(log: string): Promise<CapabilityOutcome> {
337		const byFile = readUnparameterisedBaseClasses(log);
338		const wanted = new Map<string, string>();
339		for (const [file, diagnostics] of byFile) {
340			const absolute = path.join(APPLIED_TREE, file);
341			if (!existsSync(absolute)) continue;
342			const source = await readFile(absolute, 'utf8');
343			for (const diagnostic of diagnostics) {
344				for (const line of source.split('\n')) {
345					if (!line.startsWith('import ')) continue;
346					if (!new RegExp(String.raw`\b${diagnostic.base}\b`, 'u').test(line)) continue;
347					const quote = line.indexOf("'");
348					const end = line.indexOf("'", quote + 1);
349					if (quote !== -1 && end !== -1) wanted.set(diagnostic.base, line.slice(quote + 1, end));
350				}
351			}
352		}
353		const readings: GenericBaseClassReading[] = [];
354		for (const [name, specifier] of [...wanted].sort())
355			readings.push(await readGenericBaseClass(APPLIED_TREE, name, specifier));
356		const changed: string[] = [];
357		const changes: string[] = [];
358		const unhandled: string[] = [];
359		for (const [file, diagnostics] of byFile) {
360			const absolute = path.join(APPLIED_TREE, file);
361			if (!existsSync(absolute)) {
362				unhandled.push(`${file}: the diagnostic names a file the applied tree does not carry`);
363				continue;
364			}
365			const source = await readFile(absolute, 'utf8');
366			const migration = parameteriseBaseClasses(
367				file,
368				source,
369				diagnostics as readonly UnparameterisedBaseClassDiagnostic[],
370				readings,
371			);
372			unhandled.push(...migration.unhandled);
373			if (!migration.changed) continue;
374			await writeFile(absolute, migration.source);
375			changed.push(file);
376			for (const change of migration.changes)
377				changes.push(
378					`${file} line ${String(change.line)}: ${change.base} → ${change.base}<${change.argument}> ` +
379						`from '${change.specifier}' (import added: ${String(change.importAdded)})`,
380				);
381		}
382		return Object.freeze({
383			capability:
384				'unparameterised-base-class, against ' +
385				readings
386					.map(
387						(reading) =>
388							`${reading.name} in ${reading.declaration} (${String(reading.parameters.length)} ` +
389							`parameter(s), companion: ${reading.companion?.name ?? 'none'})`,
390					)
391					.join(', '),
392			filesChanged: Object.freeze(changed),
393			changes: Object.freeze(changes),
394			unhandled: Object.freeze(unhandled),
395		});
396	}
397	
398	/** The member-rename round, driven by TS2339 lines that name a declared type. */
399	async function memberRenameRound(log: string): Promise<CapabilityOutcome> {
400		const byFile = readMissingMembers(log);
401		const surfaces: TypeMemberSurfaceReading[] = [];
402		for (const rename of DOCUMENTED_MEMBER_RENAMES)
403			surfaces.push(await readTypeMemberSurface(APPLIED_TREE, rename.package, rename.type));
404		const changed: string[] = [];
405		const changes: string[] = [];
406		const unhandled: string[] = [];
407		for (const [file, diagnostics] of byFile) {
408			const absolute = path.join(APPLIED_TREE, file);
409			if (!existsSync(absolute)) continue;
410			if (!file.endsWith('.ts')) {
411				unhandled.push(
412					`${file}: the compiler raises this TS2339 against a template, whose receiver is the ` +
413						'component class rather than a type an installed package declares',
414				);
415				continue;
416			}
417			const source = await readFile(absolute, 'utf8');
418			const migration = renameDeclaredTypeMembers(
419				file,
420				source,
421				diagnostics as readonly MissingMemberDiagnostic[],
422				DOCUMENTED_MEMBER_RENAMES,
423				surfaces,
424			);
425			unhandled.push(...migration.unhandled);
426			if (!migration.changed) continue;
427			await writeFile(absolute, migration.source);
428			changed.push(file);
429			for (const change of migration.changes)
430				changes.push(
431					`${file} line ${String(change.line)}: ${change.declaredType}.${change.from} → ` +
432						`${change.to}`,
433				);
434		}
435		return Object.freeze({
436			capability:
437				'declared-type-member-rename, against ' +
438				surfaces
439					.map(
440						(surface) =>
441							`${surface.package}@${surface.version} ${surface.type} ` +
442							`(${String(surface.members.length)} members, complete: ${String(surface.complete)})`,
443					)
444					.join(', '),
445			filesChanged: Object.freeze(changed),
446			changes: Object.freeze(changes),
447			unhandled: Object.freeze(unhandled),
448		});
449	}
450	
451	export async function main(): Promise<void> {
452		const log = await readFile(path.join(STAGE_DIRECTORY, process.argv[2] ?? 'build-3.log'), 'utf8');
453		const outcomes: CapabilityOutcome[] = [...(await applyRound())];
454		outcomes.push(await baseClassRound(log));
455		outcomes.push(await memberRenameRound(log));
456		await writeFile(
457			path.join(STAGE_DIRECTORY, 'u18e-round.json'),
458			`${JSON.stringify(outcomes, null, '\t')}\n`,
459		);
460		for (const outcome of outcomes)
461			process.stdout.write(
462				`${outcome.capability}: ${String(outcome.filesChanged.length)} files changed, ` +
463					`${String(outcome.changes.length)} changes, ${String(outcome.unhandled.length)} refused\n`,
464			);
465	}
466	
467	if (process.argv[1]?.endsWith('angular-super-productivity-u18e-run.ts'))
468		main().catch((error: unknown) => {
469			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
470			process.exitCode = 1;
471		});
