1	/**
2	 * Imports of a subpath the installed package does not publish.
3	 *
4	 * An era application often reaches past a package's public surface — `import
5	 * {X} from 'pkg/src/internal'` — because the era package had no `exports` map
6	 * and every file on disk was addressable. A package that later declares one
7	 * closes that door: the subpath is unreachable whatever is still on disk, and
8	 * the compiler reports a module it cannot find.
9	 *
10	 * This is the mirror image of {@link splitBarrelImports}. There a symbol was
11	 * reached one directory too shallow and had to move deeper; here it is reached
12	 * too deep and has to move out to whichever entry point the package actually
13	 * publishes it from. Both questions are answered by the same reading of the
14	 * installed closure — the package's own `exports` map, and the names each
15	 * published declaration file exports — so both share
16	 * {@link resolveBarrelSymbol} and neither carries a table.
17	 *
18	 * The reachable set is read, never inferred. A subpath the exports map names is
19	 * reachable even when this capability cannot type it (a `.js` or `.json` target
20	 * carries no declaration file), so an import of one is left alone rather than
21	 * redirected on the strength of a surface that was never consulted.
22	 *
23	 * Refusal is all-or-nothing per declaration, for the reason the barrel split
24	 * refuses: rewriting the symbols that do resolve would silently drop the one
25	 * that does not, turning a build error into missing behaviour.
26	 */
27	
28	import { compareStrings } from './angular-target-cell.ts';
29	import { resolveBarrelSymbol, type PackageSurfaceReading } from './barrel-entry-point-split.ts';
30	import { applySourceEdits, lineOf, parseModule, type SourceEdit } from './semantic-module.ts';
31	
32	const CAPABILITY = 'Deep import redirection';
33	
34	/**
35	 * What the installed package publishes, and which specifiers it answers.
36	 *
37	 * `reachableSpecifiers` is every specifier the exports map resolves, including
38	 * the ones with no declaration file. It is deliberately wider than the typed
39	 * entry points in `surface`: this capability only ever acts on a specifier that
40	 * is in neither, so a subpath whose target it cannot read is still safe.
41	 */
42	export type DeepImportReading = Readonly<{
43		surface: PackageSurfaceReading;
44		reachableSpecifiers: readonly string[];
45	}>;
46	
47	export type DeepImportChange = Readonly<{
48		kind: 'deep-import-redirect';
49		line: number;
50		from: string;
51		to: string;
52		symbols: readonly string[];
53	}>;
54	
55	export type DeepImportMigration = Readonly<{
56		path: string;
57		source: string;
58		changed: boolean;
59		changes: readonly DeepImportChange[];
60		unhandled: readonly string[];
61	}>;
62	
63	type ImportedSpecifier = Readonly<{ name: string; text: string }>;
64	
65	/** Whether `specifier` addresses `name` — the package root or a subpath of it. */
66	function addresses(specifier: string, name: string): boolean {
67		return specifier === name || specifier.startsWith(`${name}/`);
68	}
69	
70	/**
71	 * Rewrite one module's imports of unreachable subpaths of a package onto the
72	 * entry points the installed package publishes the named symbols from.
73	 *
74	 * Each specifier keeps its own text — an alias, a per-specifier `type` modifier
75	 * — so the rewrite moves names between declarations without restating any of
76	 * them.
77	 */
78	export function redirectUnreachableImports(
79		path: string,
80		source: string,
81		reading: DeepImportReading,
82	): DeepImportMigration {
83		const { surface } = reading;
84		const module = parseModule(CAPABILITY, path, source);
85		const edits: SourceEdit[] = [];
86		const changes: DeepImportChange[] = [];
87		const unhandled: string[] = [];
88		for (const declaration of module.ast.body) {
89			if (declaration.type !== 'ImportDeclaration') continue;
90			const specifier = declaration.source.value;
91			if (typeof specifier !== 'string') continue;
92			if (!addresses(specifier, surface.name)) continue;
93			if (reading.reachableSpecifiers.includes(specifier)) continue;
94			const line = lineOf(source, declaration.start);
95			const named: ImportedSpecifier[] = [];
96			let wide = false;
97			for (const imported of declaration.specifiers) {
98				if (imported.type !== 'ImportSpecifier' || imported.imported.type !== 'Identifier') {
99					wide = true;
100					continue;
101				}
102				named.push({
103					name: imported.imported.name,
104					text: source.slice(imported.start, imported.end),
105				});
106			}
107			if (wide) {
108				unhandled.push(
109					`${path} line ${String(line)}: ${specifier} is not a subpath ` +
110						`${surface.name}@${surface.version} publishes, and the declaration carries a default ` +
111						'or namespace binding whose members cannot be resolved to an entry point by name, so ' +
112						'it was left exactly as it is',
113				);
114				continue;
115			}
116			if (named.length === 0) {
117				unhandled.push(
118					`${path} line ${String(line)}: ${specifier} is not a subpath ` +
119						`${surface.name}@${surface.version} publishes, and the declaration names no symbol — ` +
120						'it is imported for its side effect, and nothing about the published surface says ' +
121						'which entry point runs the same one, so it was left exactly as it is',
122				);
123				continue;
124			}
125			const groups = new Map<string, ImportedSpecifier[]>();
126			const refusals: string[] = [];
127			for (const entry of named) {
128				const resolution = resolveBarrelSymbol(surface, entry.name);
129				if (resolution.kind === 'unmapped' || resolution.kind === 'ambiguous') {
130					refusals.push(resolution.reason);
131					continue;
132				}
133				const group = groups.get(resolution.specifier);
134				if (group === undefined) groups.set(resolution.specifier, [entry]);
135				else group.push(entry);
136			}
137			if (refusals.length > 0) {
138				for (const reason of refusals)
139					unhandled.push(
140						`${path} line ${String(line)}: ${specifier} is unreachable and ${reason}. The whole ` +
141							'declaration was left as it is: redirecting the symbols that do resolve would ' +
142							'delete the one that does not.',
143					);
144				continue;
145			}
146			const quote = source.slice(declaration.source.start, declaration.source.start + 1);
147			const prefix = declaration.importKind === 'type' ? 'import type' : 'import';
148			const targets = [...groups.keys()].sort(compareStrings);
149			const text = targets
150				.map((target) => {
151					const group = groups.get(target) ?? [];
152					return `${prefix} {${group.map((entry) => entry.text).join(', ')}} from ${quote}${target}${quote};`;
153				})
154				.join('\n');
155			let end = declaration.end;
156			if (source[end] === ';') end += 1;
157			edits.push({ start: declaration.start, end, text });
158			changes.push({
159				kind: 'deep-import-redirect',
160				line,
161				from: specifier,
162				to: targets.join(', '),
163				symbols: Object.freeze(named.map((entry) => entry.name).sort(compareStrings)),
164			});
165		}
166		const migrated = applySourceEdits(source, edits);
167		return Object.freeze({
168			path,
169			source: migrated,
170			changed: migrated !== source,
171			changes: Object.freeze(changes),
172			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
173		});
174	}
